const spellColors={steam:'#b8e9ec',wildfire:'#f7b064',overload:'#e4b2fc',bloom:'#b7eea4',conduction:'#a8e3ff',staticbind:'#d6e59f',dragonbreath:'#ffa865',dragonfury:'#f4b068',cloudcounter:'#e6ce87',stoneskin:'#c0bf9a',stormtalons:'#c2ccff',thunderstun:'#c2caff',oceanchorus:'#b0ece3',deepwell:'#a8e0e5',royaltide:'#b9e4cc',lightning:'#b8c9ff',chainlightning:'#b4c3ff',thunderstorm:'#c5c7ff',electriccharge:'#b7d0ff',firebreath:'#ff9d58',flameguard:'#ffc27b',tidal:'#8cdeea',waterheal:'#acebea',maelstrom:'#89cfe4',vine:'#b3d88a',thorns:'#a9d28c',wildwood:'#b5dd9b',rootstorm:'#a4cc7f',fire:'#ff9a60',inferno:'#ff9a60',astral:'#cbb2ff',comet:'#d1c4ff',nova:'#e3b9ff',supernova:'#efccff',tempest:'#9edbfa',wave:'#8de1e6',quake:'#d4c29c',bulwark:'#f2cd8f',taunt:'#f2cd8f',shield:'#b9cfff',bastion:'#b9cfff',heal:'#adf1b1',teamheal:'#adf1b1',cleanse:'#a3e5e5',lifebloom:'#caf0a5',regen:'#b8edac',buff:'#f2da9e',debuff:'#e0a5de',eclipse:'#e0a5de',attack:'#f3d5ab'};
export function renderSpellEffect(kind,move){return `<div class="vfx vfx-${kind} spell-detail" style="--spell:${spellColors[kind]||'#cbb2ff'}" aria-hidden="true"><span class="spell-rune"></span><span class="spell-core"></span><span class="spell-shockwave"></span>${Array.from({length:18},(_,i)=>`<i style="--n:${i};--angle:${i*20}deg;--distance:${48+(i%4)*12}px;--delay:${(i%3)*.035}s"></i>`).join('')}${reactionGlyph(kind)}${spellImpact(kind)}${legendSpellGlyph(kind)}<svg class="spell-glyph" viewBox="0 0 120 120"><circle cx="60" cy="60" r="47"/><path d="M60 7 106 86 14 86ZM60 113 14 34 106 34Z"/><circle cx="60" cy="60" r="28"/><path d="M60 18v10m0 64v10M18 60h10m64 0h10"/></svg></div>`;}
export function mountBattleMotion(event,quick=false){
 if(!event?.actor||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const arena=document.querySelector('.team-arena'),source=document.querySelector(`[data-target="${event.actor}"] .fighter-art`);if(!arena||!source)return;
 const rect=arena.getBoundingClientRect(),from=source.getBoundingClientRect(),sx=from.left+from.width/2-rect.left,sy=from.top+from.height*.5-rect.top,color=spellColors[event.kind]||'#cbb2ff',duration=quick?'.22s':'.65s';
 const layer=document.createElementNS('http://www.w3.org/2000/svg','svg');layer.setAttribute('class','action-path-layer');layer.setAttribute('viewBox',`0 0 ${rect.width} ${rect.height}`);layer.setAttribute('aria-hidden','true');let markup='',previous=null;
 for(const cid of event.targets){if(cid===event.actor)continue;const target=document.querySelector(`[data-target="${cid}"] .fighter-art`);if(!target)continue;const t=target.getBoundingClientRect(),tx=t.left+t.width/2-rect.left,ty=t.top+t.height*.5-rect.top,path=`M${sx},${sy} Q${(sx+tx)/2+45},${(sy+ty)/2-55} ${tx},${ty}`;
 if(['lightning','chainlightning','thunderstorm','electriccharge','thunderstun','conduction','overload','staticbind'].includes(event.kind)){const start=['chainlightning','conduction'].includes(event.kind)&&previous?previous:event.kind==='thunderstorm'?{x:tx-22,y:8}:{x:sx,y:sy};const bolt=lightningPath(start.x,start.y,tx,ty);markup+=`<path class="lightning-link lightning-halo" d="${bolt}" fill="none" stroke="${color}" stroke-width="7"/><path class="lightning-link lightning-core" d="${bolt}" fill="none" stroke="#f1f5ff" stroke-width="2"/>`;previous={x:tx,y:ty};continue;}if(['firebreath','dragonbreath'].includes(event.kind)){const cone=`M${sx},${sy} Q${(sx+tx)/2-18},${(sy+ty)/2} ${tx-22},${ty+10} L${tx+22},${ty-10} Q${(sx+tx)/2+18},${(sy+ty)/2} ${sx},${sy}Z`;markup+=`<path class="breath-cone" d="${cone}" fill="${color}"/>`;}markup+=`<path class="cast-thread" d="${path}" fill="none" stroke="${color}" stroke-width="2" pathLength="100"/><circle r="7" fill="${color}" class="spell-projectile"><animateMotion dur="${duration}" path="${path}" fill="freeze"/><animate attributeName="opacity" values="0;1;1;0" dur="${duration}" fill="freeze"/></circle><circle r="3" fill="#fff6dc" class="spell-projectile"><animateMotion begin=".06s" dur="${duration}" path="${path}" fill="freeze"/><animate attributeName="opacity" values="0;1;1;0" dur="${duration}" fill="freeze"/></circle>`;
 }
 for(const effect of event.effects.filter(e=>e.counter)){const attacker=document.querySelector(`[data-target="${effect.retaliationFrom}"] .fighter-art`),victim=document.querySelector(`[data-target="${effect.cid}"] .fighter-art`);if(!attacker||!victim)continue;const a=attacker.getBoundingClientRect(),t=victim.getBoundingClientRect(),ax=a.left+a.width/2-rect.left,ay=a.top+a.height/2-rect.top,tx=t.left+t.width/2-rect.left,ty=t.top+t.height/2-rect.top;markup+=`<path class="counter-link" d="M${ax},${ay} Q${(ax+tx)/2+40},${(ay+ty)/2-35} ${tx},${ty}" fill="none" stroke="#f5daa0" stroke-width="4" pathLength="100"/>`;}layer.innerHTML=markup;arena.append(layer);
 if(['steam','wildfire','overload','bloom','conduction','staticbind','supernova','inferno','tempest','quake','teamheal','lifebloom','firebreath','thunderstorm','tidal','maelstrom','rootstorm','dragonbreath','royaltide','oceanchorus'].includes(event.kind)){const flash=document.createElement('div');flash.className='arena-spell-glow';flash.style.setProperty('--spell',color);arena.append(flash);}
}

function lightningPath(sx,sy,tx,ty){const dx=tx-sx,dy=ty-sy,length=Math.hypot(dx,dy)||1,amplitude=Math.min(23,length*.09);let path=`M${sx},${sy}`;for(let i=1;i<10;i++){const offset=(i%2?1:-1)*amplitude*(i%3===0 ? .6 : 1);path+=` L${sx+dx*i/10-dy/length*offset},${sy+dy*i/10+dx/length*offset}`;}return path+` L${tx},${ty}`;}
function spellImpact(kind){if(['lightning','chainlightning','thunderstorm','electriccharge','thunderstun','conduction','overload','staticbind'].includes(kind))return `<svg class="lightning-impact" viewBox="0 0 120 120"><path d="M72 6 35 59h25l-14 55 42-67H62Z"/><path class="small-bolt" d="m24 17-9 20h10l-6 18 16-27H24m73 45-10 18h10l-6 18 17-27H98"/></svg>`;if(['vine','thorns','wildwood','rootstorm'].includes(kind))return `<svg class="root-impact" viewBox="0 0 120 120"><path d="M60 112Q25 83 44 58T33 8m27 104q35-29 16-54T87 8M46 66 21 48m52 18 26-20M42 33 60 18m21 18L65 21"/><path class="leaf-impact" d="M43 58Q14 32 22 28Q47 27 43 58m33 1q28-25 23-31q-27-1-23 31"/></svg>`;return '';}

function legendSpellGlyph(kind){if(kind==='cloudcounter')return `<svg class="legend-spell-glyph cloud-glyph" viewBox="0 0 120 120"><path d="M20 84q-13-15 7-18q-3-18 18-13q17-20 32-2q25-12 27 10q20 4 9 21Z"/><path class="staff-symbol" d="m37 27 44 54M32 31l10-8m34 61 11-9"/></svg>`;if(kind==='stoneskin')return `<svg class="legend-spell-glyph stone-glyph" viewBox="0 0 120 120"><path d="m60 9 44 25-5 51-39 27-39-27-5-51Z"/><path d="m60 9-9 38 21 18-12 47M16 34l35 13m21 18 27 20"/></svg>`;if(['royaltide','oceanchorus','deepwell'].includes(kind))return `<svg class="legend-spell-glyph tide-crown" viewBox="0 0 120 120"><path d="m25 48 10 34h50l10-34-20 13-15-27-15 27Z"/><circle cx="60" cy="37" r="5"/><path d="M16 94q11-12 22 0t22 0t22 0t22 0"/></svg>`;if(['dragonbreath','dragonfury','stormtalons'].includes(kind))return `<svg class="legend-spell-glyph claw-glyph" viewBox="0 0 120 120"><path d="M30 20 12 98 46 27M61 16 41 104 78 24M92 21 72 99 109 29"/></svg>`;return '';}

function reactionGlyph(kind){if(!['steam','wildfire','overload','bloom','conduction','staticbind'].includes(kind))return '';return `<svg class="reaction-impact reaction-impact-${kind}" viewBox="0 0 120 120"><circle class="reaction-orbit" cx="60" cy="60" r="45"/><circle class="reaction-orbit reverse-orbit" cx="60" cy="60" r="35"/><path d="M22 82Q5 43 40 28m58 10q17 39-18 54"/>${kind==='steam'?'<path class="steam-plume" d="M37 90q-23-16 0-33t0-34m23 67q-23-16 0-33t0-34m23 67q-23-16 0-33t0-34"/>':kind==='bloom'?'<path d="M60 60Q12 9 25 57q-22 26 35 3Zm0 0q48-51 35-3q22 26-35 3Zm0 0q-28-68 0-42q28-26 0 42Zm0 0v48"/>':kind==='wildfire'?'<path d="M61 8Q35 44 53 53Q24 34 29 77Q35 111 66 108Q102 98 94 61L75 31Q81 71 61 76Q45 61 61 8Z"/>':''}</svg>`;}
